export type Category =
  | "Research"
  | "Internship"
  | "Competition"
  | "Summer Program"
  | "Scholarship"
  | "Volunteer"
  | "Fellowship";

export type Opportunity = {
  id: string;
  title: string;
  org: string;
  category: Category;
  fields: string[];
  location: string;
  format: "In-person" | "Online" | "Hybrid";
  cost: "Free" | "Paid" | "Stipend";
  grades: number[]; // 9-12
  deadline: string; // ISO
  prestige: 1 | 2 | 3; // 3 = top tier
  blurb: string;
  url: string;
};

